quests[9015] = { id = 9015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Challenge", description = "Heed me well, {name}.  For the banner to work in the desired way, you will need to step into the Ring of the Law in Blackrock Depths.  Allow yourself to be sentenced by High Justice Grimstone and place the banner firmly on the ground in a sign of defiance.\n\nYour victim will not be able to restrain himself and shall enter the fray filled with a desire to fight you.  Once you obtain that which you seek, go back to Anthion.", sourceObjective = "Travel to the Ring of the Law in Blackrock Depths and place the Banner of Provocation in its center as you are sentenced by High Justice Grimstone. Slay Theldren and his gladiators and return to Anthion Harmon in the Eastern Plaguelands with the first piece of Lord Valthalak's amulet.", progress = "You're back, {name}!", completion = "You've recovered part of the medallion, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[9016] = { id = 9016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Mokvar in Orgimmar with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.", progress = "You've returned and I see in your eyes that you've much to tell me, {name}.  Let us take care of your reward first.", completion = "This curse was bestowed upon us but for a mere medallion.  Lord Valthalak certainly knows how to hold a grudge.\n\nWe'll endeavor to find the remaining pieces - hopefully before I meet an untimely demise.  But before that, let us see about your reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[9017] = { id = 9017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Mokvar in Orgimmar with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle.", progress = "You've returned and I see in your eyes that you've much to tell me, {name}.  Let us take care of your reward first.", completion = "This curse was bestowed upon us but for a mere medallion.  Lord Valthalak certainly knows how to hold a grudge.\n\nWe'll endeavor to find the remaining pieces - hopefully before I meet an untimely demise.  But before that, let us see about your reward.", sourceObjectiveStatus = "unverified-source-field" }
