quests[9102] = { id = 9102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfire Bindings", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", sourceObjective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Bindings if you bring her the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, {class}. Use discretion when donning Frostfire.", sourceObjectiveStatus = "unverified-source-field" }
quests[9103] = { id = 9103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagueheart Robe", description = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.\n\nAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die; but I've already explained this...", sourceObjective = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands will make a Plagueheart Robe if you bring him the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n<Mataus shakes his head disapprovingly.>\n\nNow take it and get out of my sight.", sourceObjectiveStatus = "unverified-source-field" }
