quests[9111] = { id = 9111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Robe of Faith", description = "<Father Montoy makes some strange gestures in the air in front of you.>\n\nBlessed <boy/girl>, have you found the vestments of the fallen? The poor souls whose last breaths were taken on the field of battle - stripped of everything including their dignity.\n\nBring me the desecrated remnants of the departed along with reagents of purification and you shall know faith.", sourceObjective = "Father Inigo Montoy at Light's Hope Chapel in the Eastern Plaguelands will make a Robe of Faith if you bring him the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", progress = "Have you brought me the reagents, child?", completion = "The vestments are ready, {name}. Smite those that would harm our world in your righteous fire.", sourceObjectiveStatus = "unverified-source-field" }
